#!/usr/bin/env pwsh -NoProfile -ExecutionPolicy Bypass -Command & { <# Self-elevate if not admin #> $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator); if (-not $isAdmin) { Start-Process pwsh -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', ('{0}' -f $PSCommandPath)) -Verb RunAs -Wait; exit } <# Main script below #> } # TheSeed Auto-Sync Daemon v2.0 # Roadmap: 02_REPO_ARCHITECTURE.md §6, §9.3 # Branching: main/develop/feature/* (§3.1) # Commit-Format: Conventional Commits (§3.2) # # Usage: Right-click -> Run with PowerShell # Or: pwsh -File scripts/auto-sync.ps1 # # Place this file in: TheSeed/scripts/auto-sync.ps1 # Place config in:     TheSeed/scripts/auto-sync.config.json param( [int]$IntervalMinutes = 5, [string]$LogFile = 'scripts/auto-sync.log', [string]$ConfigFile = 'scripts/auto-sync.config.json' ) $ErrorActionPreference = 'Continue' $ProgressPreference = 'SilentlyContinue' $root = Split-Path $PSScriptRoot -Parent $logPath = Join-Path $root $LogFile $lockFile = Join-Path $root '.auto-sync.lock' # ============================================================================= # CONFIGURATION # ============================================================================= $config = @{ interval_minutes = $IntervalMinutes branches = @('main', 'develop') stash_on_dirty = $true test_after_sync = $false max_log_size_mb = 10 discord_webhook = $null # Set to Discord webhook URL for notifications } $configPath = Join-Path $root $ConfigFile if (Test-Path $configPath) { try { $loaded = Get-Content $configPath -Raw | ConvertFrom-Json -ErrorAction Stop $loaded.PSObject.Properties | ForEach-Object { $config[$_.Name] = $_.Value } } catch { Write-Host 'Failed to load config. Using defaults.' -ForegroundColor Yellow } } # ============================================================================= # LOCK FILE & SINGLE INSTANCE # ============================================================================= if (Test-Path $lockFile) { $pidOld = Get-Content $lockFile -ErrorAction SilentlyContinue if ($pidOld -and (Get-Process -Id $pidOld -ErrorAction SilentlyContinue)) { Write-Host 'Auto-sync already running (PID: {0})' -f $pidOld -ForegroundColor Red Write-Host 'Use stop-auto-sync.cmd to stop it first.' -ForegroundColor Yellow pause exit 1 } Remove-Item $lockFile -Force } $PID | Set-Content $lockFile # ============================================================================= # GRACEFUL SHUTDOWN # ============================================================================= $syncActive = $true Register-EngineEvent -SourceIdentifier PowerShell.Exiting -Action { Remove-Item $lockFile -ErrorAction SilentlyContinue } | Out-Null trap { Write-Log 'Interrupted by user. Cleaning up...' 'WARN' Remove-Item $lockFile -ErrorAction SilentlyContinue $syncActive = $false break } # ============================================================================= # LOGGING # ============================================================================= function Write-Log { param([string]$Message, [string]$Level = 'INFO') $timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss' $line = '[$timestamp] [$Level] $Message' Add-Content -Path $logPath -Value $line -ErrorAction SilentlyContinue $color = switch ($Level) { 'ERROR' { 'Red' } 'WARN'  { 'Yellow' } 'OK'    { 'Green' } default { 'White' } } Write-Host $line -ForegroundColor $color } # Log rotation if ((Get-Item $logPath -ErrorAction SilentlyContinue).Length -gt ($config.max_log_size_mb * 1MB)) { $ts = Get-Date -Format 'yyyyMMdd-HHmmss' Move-Item $logPath ('$logPath.$ts') -Force -ErrorAction SilentlyContinue } # ============================================================================= # MAIN LOOP # ============================================================================= Write-Log '=== TheSeed Auto-Sync v2.0 started (PID: $PID) ===' Write-Log 'Config: interval=$($config.interval_minutes)m, branches=[$($config.branches -join ', ')]' Write-Log 'Logging to: $logPath' Write-Host '' Set-Location $root $consecutiveErrors = 0 while ($syncActive) { try { Write-Log '--- Sync cycle started ---' $currentBranch = git rev-parse --abbrev-ref HEAD 2>$null if ($LASTEXITCODE -ne 0) { throw 'Not a git repository or git not available' } if ($currentBranch -notin $config.branches) { Write-Log 'Branch ''$currentBranch'' not in watchlist. Skipping cycle.' 'WARN' Start-Sleep -Seconds ($config.interval_minutes * 60) continue } # 1. Stash if dirty $stashCreated = $false $dirty = git status --porcelain 2>$null if ($dirty -and $config.stash_on_dirty) { Write-Log 'Working tree dirty. Stashing local changes...' 'WARN' git stash push -m 'auto-sync-stash-$(Get-Date -Format 'yyyyMMdd-HHmmss')' 2>$null $stashCreated = $true } # 2. Fetch + check if update needed git fetch origin $currentBranch 2>$null $localHash = git rev-parse HEAD 2>$null $remoteHash = git rev-parse 'origin/$currentBranch' 2>$null if ($localHash -eq $remoteHash) { Write-Log 'TheSeed: Already up to date ($currentBranch @ $localHash)' 'OK' } else { Write-Log 'TheSeed: Remote ahead. Pulling $currentBranch...' $pullOutput = git pull origin $currentBranch 2>&1 if ($LASTEXITCODE -ne 0) { throw 'Pull failed: $pullOutput' } if ($pullOutput -match 'CONFLICT|conflict|Merge conflict') { throw 'MERGE CONFLICT detected! Manual resolution required on $currentBranch.' } Write-Log 'TheSeed: Updated $currentBranch ($localHash -> $remoteHash)' 'OK' } # 3. Update submodules (pinned, NOT --remote!) Write-Log 'Updating submodules to pinned commits...' git submodule update --init --recursive 2>$null if ($LASTEXITCODE -ne 0) { throw 'Submodule update failed' } Write-Log 'Submodules synced to pinned commits' 'OK' # 4. Commit submodule pointer changes if needed $status = git status --short 2>$null if ($status -match 'submodules/') { $submoduleShort = git -C submodules/seed-core rev-parse --short HEAD 2>$null git add submodules/ 2>$null $commitMsg = @'chore(submodule): auto-sync seed-core - Pointer: $submoduleShort - Time: $(Get-Date -Format 'yyyy-MM-dd HH:mm') Refs: auto-sync '@ git commit -m '$commitMsg' 2>$null | Out-Null Write-Log 'Submodule pointer committed ($submoduleShort)' 'OK' } # 5. Push local commits (only auto-sync commits, safely) $localCommits = git log 'origin/$currentBranch..HEAD' --oneline 2>$null if ($localCommits) { $count = ($localCommits | Measure-Object).Count Write-Log 'Pushing $count local commit(s) to origin/$currentBranch...' git push --force-with-lease origin $currentBranch 2>&1 | Out-Null if ($LASTEXITCODE -ne 0) { throw 'Push failed' } Write-Log 'Push complete' 'OK' } else { Write-Log 'Nothing to push' 'OK' } # 6. Restore stashed changes if ($stashCreated) { git stash pop 2>$null Write-Log 'Stashed changes restored' 'OK' } # 7. Optional: quick build check if ($config.test_after_sync) { Write-Log 'Running quick build check...' $buildDir = Join-Path $root 'build' if (Test-Path $buildDir) { $buildCheck = cmake --build $buildDir --target seed-core 2>&1 if ($LASTEXITCODE -ne 0) { Write-Log 'BUILD BROKEN after sync! Check immediately.' 'ERROR' } else { Write-Log 'Build check passed' 'OK' } } else { Write-Log 'Build directory not found, skipping build check' 'WARN' } } $consecutiveErrors = 0 Write-Log '--- Sync cycle complete ---' } catch { $consecutiveErrors++ Write-Log 'ERROR (consecutive: $consecutiveErrors): $_' 'ERROR' if ($consecutiveErrors -ge 3 -and $config.discord_webhook) { try { $body = @{ content = ':warning: **TheSeed Auto-Sync**: 3 consecutive failures on ``$env:COMPUTERNAME``! Check logs: ``$logPath``' } | ConvertTo-Json Invoke-RestMethod -Uri $config.discord_webhook -Method Post -Body $body -ContentType 'application/json' -ErrorAction SilentlyContinue | Out-Null } catch {} } } if ($syncActive) { Write-Log 'Sleeping for $($config.interval_minutes) minutes...' Start-Sleep -Seconds ($config.interval_minutes * 60) } } Write-Log 'Daemon stopped gracefully.' Remove-Item $lockFile -ErrorAction SilentlyContinue